{
  "diagnosis": "Common Cold (Infeksi Saluran Pernapasan Akut ringan)",
  "diagnosis_reasoning": "Gejala batuk, hidung meler, dan nyeri otot (pegal) yang muncul setelah terpapar cuaca dingin/hujan sangat konsisten dengan infeksi virus pada saluran pernapasan atas.",
  "follow_up_questions": [
    "Apakah Anda mengalami demam dengan suhu tubuh di atas 38 derajat Celcius?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Gejala bersifat ringan, umum terjadi, dan tidak menunjukkan adanya tanda-tanda kegawatdaruratan pernapasan atau infeksi berat."
}

{
  "diagnosis": "Konjungtivitis Bakteri",
  "diagnosis_reasoning": "Gejala mata merah, gatal, serta adanya sekret (belek) kekuningan yang menyebabkan mata lengket saat bangun tidur merupakan tanda khas infeksi konjungtiva akibat bakteri.",
  "follow_up_questions": [
    "Apakah Anda mengalami penurunan ketajaman penglihatan, pandangan kabur, atau nyeri hebat pada bola mata?",
    "Apakah Anda merasa sensitif terhadap cahaya (fotofobia)?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Kondisi ini umumnya tidak bersifat mengancam penglihatan jika tidak disertai nyeri hebat, gangguan tajam penglihatan, atau fotofobia, namun tetap memerlukan penanganan medis untuk pemberian antibiotik topikal."
}

{
  "diagnosis": "Keseleo pergelangan kaki (ankle sprain) dengan kemungkinan cedera jaringan lunak atau fraktur minor",
  "diagnosis_reasoning": "Trauma mekanis akibat terpeleset diikuti dengan nyeri, bengkak, dan memar (kebiruan) adalah tanda khas cedera ligamen atau fraktur pada sendi pergelangan kaki.",
  "follow_up_questions": [
    "Apakah Anda mampu menumpu beban berat badan pada kaki kanan tersebut untuk berjalan setidaknya 4 langkah setelah kejadian?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Adanya pembengkakan dan perubahan warna (kebiruan) menandakan adanya kerusakan jaringan yang signifikan. Diperlukan pemeriksaan fisik dan kemungkinan rontgen (X-ray) untuk menyingkirkan adanya keretakan atau patah tulang."
}

{
  "diagnosis": "Tension-type headache (Sakit kepala tegang)",
  "diagnosis_reasoning": "Nyeri bilateral pada pelipis yang muncul setelah durasi kerja yang lama di depan komputer dan memburuk di sore hari adalah karakteristik klasik sakit kepala tegang yang dipicu oleh kelelahan otot leher dan bahu serta postur tubuh.",
  "follow_up_questions": [
    "Apakah Anda merasakan otot leher atau bahu yang kaku dan tegang saat sakit kepala muncul?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Gejala bersifat kronis dan situasional (berkaitan dengan aktivitas kerja) tanpa adanya tanda bahaya (red flags) seperti penurunan kesadaran, kelemahan anggota gerak, atau gangguan penglihatan mendadak yang memerlukan penanganan segera."
}

{
  "diagnosis": "Insomnia psikofisiologis (onset insomnia)",
  "diagnosis_reasoning": "Pasien mengalami kesulitan memulai tidur (sleep onset latency) selama 4 hari yang berdampak pada fungsi siang hari (disfungsi kognitif dan emosional), sering kali dipicu oleh beban stres akademis yang umum pada mahasiswa tingkat akhir.",
  "follow_up_questions": [
    "Apakah Anda mengonsumsi kafein dalam jumlah berlebih atau menggunakan gawai tepat sebelum waktu tidur?",
    "Apakah Anda merasa ada kecemasan berlebih atau pikiran yang terus berputar (racing thoughts) saat mencoba untuk tidur?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Kondisi ini tidak menunjukkan tanda-tanda kegawatdaruratan medis atau risiko nyawa segera, namun memerlukan manajemen pola tidur dan kesehatan mental yang tepat."
}

{
  "diagnosis": "Anemia",
  "diagnosis_reasoning": "Gejala pusing, mudah lelah, kulit pucat, dan palpitasi (jantung berdebar) merupakan manifestasi klinis klasik dari penurunan kadar hemoglobin atau sel darah merah yang menyebabkan kurangnya suplai oksigen ke jaringan.",
  "follow_up_questions": [
    "Apakah Anda mengalami perdarahan yang lebih banyak dari biasanya saat menstruasi atau memiliki riwayat pola makan yang kurang asupan zat besi?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala menunjukkan kondisi kronis yang memerlukan pemeriksaan laboratorium (seperti tes darah lengkap) untuk konfirmasi diagnosis, namun tidak menunjukkan tanda kegawatdaruratan yang mengancam nyawa secara langsung saat ini."
}

{
  "diagnosis": "Infeksi Saluran Kemih (ISK) bagian bawah / Sistitis",
  "diagnosis_reasoning": "Gejala disuria (nyeri saat buang air kecil), frekuensi berkemih yang meningkat, dan nyeri suprapubik adalah tanda klinis klasik dari peradangan kandung kemih yang paling sering disebabkan oleh infeksi bakteri.",
  "follow_up_questions": [
    "Apakah Anda mengalami demam, menggigil, atau nyeri pada area pinggang belakang?",
    "Apakah terdapat perubahan warna pada urine, seperti keruh atau bercampur darah?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Kondisi ini memerlukan evaluasi medis dan pemberian antibiotik untuk mencegah infeksi menyebar ke ginjal (pielonefritis), namun tidak bersifat mengancam nyawa secara langsung selama tidak ada tanda komplikasi sistemik."
}

{
  "diagnosis": "Eksaserbasi asma (serangan asma)",
  "diagnosis_reasoning": "Gejala napas berat dan berdesis (mengi) yang dipicu oleh aktivitas fisik (exercise-induced bronchoconstriction) pada individu dengan riwayat asma yang tidak terkontrol merupakan tanda khas penyempitan saluran napas.",
  "follow_up_questions": [
    "Apakah Anda mengalami sesak napas yang membuat Anda sulit berbicara dalam satu kalimat utuh atau merasa sangat kelelahan saat bernapas?"
  ],
  "triage": "darurat",
  "triage_reasoning": "Sesak napas dan mengi yang muncul mendadak pada pasien dengan riwayat asma yang tidak menggunakan pengobatan rutin (steroid inhalasi) berisiko tinggi menyebabkan gagal napas jika tidak ditangani segera dengan bronkodilator."
}

{
  "diagnosis": "Benign Paroxysmal Positional Vertigo (BPPV)",
  "diagnosis_reasoning": "Gejala vertigo episodik yang dipicu oleh perubahan posisi (saat bangun tidur) dengan durasi singkat (beberapa detik) sangat khas untuk BPPV, meskipun stroke vaskular harus tetap disingkirkan pada usia 52 tahun.",
  "follow_up_questions": [
    "Apakah Anda mengalami keluhan lain seperti bicara pelo, kelemahan anggota gerak sebelah sisi, penurunan kesadaran, atau gangguan penglihatan ganda?",
    "Apakah vertigo dipicu oleh gerakan kepala tertentu, seperti menoleh atau mengubah posisi tidur?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Meskipun gejala mengarah pada BPPV, keluhan vertigo mendadak pada usia di atas 50 tahun memerlukan evaluasi medis segera untuk menyingkirkan kemungkinan penyebab neurologis serius seperti stroke atau gangguan vaskular."
}

{
  "diagnosis": "Hipoglikemia",
  "diagnosis_reasoning": "Gejala keringat dingin, gemetar, dan pandangan kabur pada pasien diabetes yang mengonsumsi obat namun melewatkan makan (asupan karbohidrat kurang) sangat mengarah pada kondisi kadar gula darah rendah (hipoglikemia).",
  "follow_up_questions": [
    "Apakah Anda memiliki alat cek gula darah (glukometer) dan berapa hasil pembacaannya saat ini?"
  ],
  "triage": "darurat",
  "triage_reasoning": "Hipoglikemia pada penderita diabetes dapat menyebabkan penurunan kesadaran atau kejang jika tidak segera ditangani dengan asupan glukosa cepat. Diperlukan tindakan segera untuk menstabilkan kadar gula darah."
}

{
  "diagnosis": "Dermatitis kontak iritan",
  "diagnosis_reasoning": "Gejala gatal, kemerahan, dan bentol berair (vesikel) muncul tepat setelah kontak dengan bahan kimia baru (sabun cuci piring), yang menunjukkan reaksi peradangan kulit akibat paparan zat iritan.",
  "follow_up_questions": [
    "Apakah keluhan gatal dan kemerahan hanya terbatas pada area kulit yang terkena sabun atau menyebar ke area tubuh lain?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Kondisi ini bersifat lokal dan tidak menunjukkan tanda-tanda reaksi alergi sistemik berat (seperti sesak napas atau pembengkakan wajah) yang memerlukan tindakan darurat."
}

{
  "diagnosis": "Apendisitis akut",
  "diagnosis_reasoning": "Migrasi nyeri dari area periumbilikal (pusar) ke kuadran kanan bawah (titik McBurney) disertai gejala gastrointestinal seperti mual dan anoreksia sangat khas untuk indikasi peradangan usus buntu.",
  "follow_up_questions": [
    "Apakah Anda mengalami demam atau nyeri yang semakin hebat saat batuk, bersin, atau saat kaki kanan digerakkan?"
  ],
  "triage": "darurat",
  "triage_reasoning": "Gejala yang dijelaskan sangat sugestif terhadap apendisitis. Keterlambatan penanganan dapat berisiko menyebabkan perforasi (usus buntu pecah), sehingga memerlukan evaluasi medis segera di Instalasi Gawat Darurat."
}

{
  "diagnosis": "Demam Tifoid (Tipes)",
  "diagnosis_reasoning": "Pola demam yang meningkat di sore/malam hari (step-ladder fever), nyeri perut, dan penurunan nafsu makan pada dewasa muda dengan riwayat sering makan di luar sangat konsisten dengan infeksi Salmonella typhi.",
  "follow_up_questions": [
    "Apakah Anda mengalami gangguan buang air besar, seperti diare atau justru sembelit dalam seminggu terakhir?",
    "Apakah lidah Anda terasa pahit atau tampak kotor (berwarna putih di tengah dengan pinggiran merah)?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala telah berlangsung selama seminggu dengan penurunan nafsu makan yang signifikan. Diperlukan pemeriksaan fisik dan laboratorium (seperti tes Widal atau Tubex) untuk mencegah komplikasi seperti perforasi usus atau perdarahan gastrointestinal."
}
